<script setup lang="ts">
import { computed } from 'vue';
import ProviderBrand from '@/Components/ProviderBrand.vue';
import { useForm } from '@inertiajs/vue3';
import { useBusinessCopy } from '@/localization/business';
export type GuidanceRow = { provider: string; priority: number; rationale_ar: string; rationale_en: string; active: boolean };
export type PriorRow = { id: number; version: number; provider: string; product: string; basis: string; documented_basis: string; applicability: string; limits: string; rationale_ar: string; rationale_en: string; internal_rationale: string; approved: boolean; active: boolean };
export type BusinessType = { id: number; version: number; key: string; name_ar: string; name_en: string; active: boolean; source_guidance: GuidanceRow[]; promotion_priors: PriorRow[] };
const props = defineProps<{ type: BusinessType; providers: { key: string; label: string }[]; products: { key: string; provider: string; label_ar: string; label_en: string }[]; canManage: boolean }>();
const { locale, localized } = useBusinessCopy();
const c = (ar: string, en: string) => locale.value === 'ar' ? ar : en;
const typeForm = useForm({ key: props.type.key, name_ar: props.type.name_ar, name_en: props.type.name_en, active: props.type.active, version: props.type.version });
const guidance = useForm({ provider: '', priority: 1, rationale_ar: '', rationale_en: '', active: true });
const initialPrior = { id: null as number | null, version: null as number | null, provider: '', product: '', basis: 'ADMIN_APPROVED_HYPOTHESIS', documented_basis: '', applicability: '', limits: '', rationale_ar: '', rationale_en: '', internal_rationale: '', approved: false, active: false };
const prior = useForm({ ...initialPrior });
const relevantProducts = computed(() => props.products.filter(product => product.provider === prior.provider));
function editGuidance(row: GuidanceRow) { Object.assign(guidance, { provider: row.provider, priority: row.priority, rationale_ar: row.rationale_ar, rationale_en: row.rationale_en, active: row.active }); guidance.clearErrors(); }
function editPrior(row: PriorRow) { Object.assign(prior, row); prior.clearErrors(); }
function clearPrior() { Object.assign(prior, initialPrior); prior.clearErrors(); }
function saveType() { typeForm.post(route('internal.business-types.update', props.type.id), { preserveScroll: true, onSuccess: () => { typeForm.version = props.type.version; } }); }
function savePrior() { prior.transform(data => { const { id, version, ...fields } = data; return id === null ? fields : { ...fields, id, version }; }).post(route('internal.business-types.prior', props.type.id), { preserveScroll: true, onSuccess: () => { if (prior.id) { const row = props.type.promotion_priors.find(row => row.id === prior.id); if (row) Object.assign(prior, row); } else clearPrior(); } }); }
</script>
<template>
    <article class="catalog-type">
        <header><div><h2>{{ localized(type) }}</h2><p dir="ltr">{{ type.key }}</p></div><span class="catalog-state">{{ type.active ? c('متاح للاختيار', 'Available for selection') : c('غير متاح للاختيار الجديد', 'Unavailable for new selection') }}</span></header>
        <details><summary>{{ c('تعريف النوع', 'Type definition') }}</summary><p v-if="!canManage" class="catalog-note">{{ type.name_ar }} / {{ type.name_en }}</p><form v-if="canManage" class="catalog-form" @submit.prevent="saveType"><label>{{ c('المفتاح', 'Key') }}<input v-model="typeForm.key" dir="ltr" required :disabled="!canManage" /></label><label>{{ c('الاسم بالعربية', 'Arabic name') }}<input v-model="typeForm.name_ar" dir="rtl" required :disabled="!canManage" /></label><label>{{ c('الاسم بالإنجليزية', 'English name') }}<input v-model="typeForm.name_en" dir="ltr" required :disabled="!canManage" /></label><label class="catalog-check"><input v-model="typeForm.active" type="checkbox" :disabled="!canManage" />{{ c('متاح للاختيار الجديد', 'Available for new selection') }}</label><p v-for="(message, field) in typeForm.errors" :key="field" role="alert" class="catalog-error">{{ message }}</p><p v-if="typeForm.recentlySuccessful" role="status">{{ c('تم الحفظ.', 'Saved.') }}</p><button v-if="canManage" :disabled="typeForm.processing">{{ c('حفظ التعريف', 'Save definition') }}</button></form></details>
        <details><summary>{{ c('توجيه المصادر', 'Source guidance') }} · {{ type.source_guidance.length }}</summary><ul class="catalog-records"><li v-for="row in type.source_guidance" :key="row.provider"><div><strong class="catalog-provider"><ProviderBrand :provider="row.provider" :size="32" />{{ providers.find(provider => provider.key === row.provider)?.label ?? row.provider }}</strong><span> · {{ row.priority }} · {{ row.active ? c('نشط', 'Active') : c('غير نشط', 'Inactive') }}</span><p>{{ locale === 'ar' ? row.rationale_ar : row.rationale_en }}</p></div><button v-if="canManage" type="button" @click="editGuidance(row)">{{ c('تعديل', 'Edit') }}</button></li></ul><form v-if="canManage" class="catalog-form" @submit.prevent="guidance.post(route('internal.business-types.guidance', type.id), { preserveScroll: true })"><label>{{ c('المزوّد', 'Provider') }}<select v-model="guidance.provider" required><option disabled value="">{{ c('اختر المزوّد', 'Choose provider') }}</option><option v-for="provider in providers" :key="provider.key" :value="provider.key">{{ provider.label }}</option></select></label><label>{{ c('ترتيب العرض', 'Display priority') }}<input v-model="guidance.priority" type="number" min="1" required /></label><label>{{ c('المبرر بالعربية', 'Arabic rationale') }}<textarea v-model="guidance.rationale_ar" dir="rtl" required /></label><label>{{ c('المبرر بالإنجليزية', 'English rationale') }}<textarea v-model="guidance.rationale_en" dir="ltr" required /></label><label class="catalog-check"><input v-model="guidance.active" type="checkbox" />{{ c('نشط', 'Active') }}</label><p v-for="(message, field) in guidance.errors" :key="field" class="catalog-error" role="alert">{{ message }}</p><p v-if="guidance.recentlySuccessful" role="status">{{ c('تم الحفظ.', 'Saved.') }}</p><button :disabled="guidance.processing">{{ c('حفظ توجيه المصدر', 'Save source guidance') }}</button></form></details>
        <details><summary>{{ c('الاعتبارات الأولية للترويج', 'Promotion priors') }} · {{ type.promotion_priors.length }}</summary><p class="catalog-note">{{ c('التغييرات في معنى الاعتبار أو مجال انطباقه تُبطل الموافقة السابقة وتحتاج إلى موافقة جديدة. التصحيحات الشكلية وحدها لا تُبطل الموافقة. التفعيل مستقل عن الموافقة.', 'Changes to a prior’s meaning or applicability invalidate prior approval and need renewed approval. Cosmetic corrections alone retain approval. Activation is separate from approval.') }}</p><ul class="catalog-records"><li v-for="row in type.promotion_priors" :key="row.id"><div><strong class="catalog-provider"><ProviderBrand :provider="row.provider" :size="32" />{{ products.find(product => product.key === row.product && product.provider === row.provider) ? localized(products.find(product => product.key === row.product && product.provider === row.provider)) : row.product }}</strong><p>{{ locale === 'ar' ? row.rationale_ar : row.rationale_en }}</p><span>{{ row.approved ? c('معتمد', 'Approved') : c('بانتظار الموافقة', 'Awaiting approval') }} · {{ row.active ? c('نشط', 'Active') : c('غير نشط', 'Inactive') }}</span></div><button v-if="canManage" type="button" @click="editPrior(row)">{{ c('تعديل / مراجعة', 'Edit / review') }}</button></li></ul>
            <form v-if="canManage" class="catalog-form" @submit.prevent="savePrior"><h3>{{ prior.id ? c('مراجعة اعتبار قائم', 'Review existing prior') : c('اعتبار جديد', 'New prior') }}</h3><button v-if="prior.id" type="button" @click="clearPrior">{{ c('بدء اعتبار جديد', 'Start a new prior') }}</button><label>{{ c('المزوّد', 'Provider') }}<select v-model="prior.provider" required @change="prior.product = ''"><option disabled value="">{{ c('اختر المزوّد', 'Choose provider') }}</option><option v-for="provider in providers" :key="provider.key" :value="provider.key">{{ provider.label }}</option></select></label><label>{{ c('القناة / المنتج', 'Channel / product') }}<select v-model="prior.product" required><option disabled value="">{{ c('اختر المنتج', 'Choose product') }}</option><option v-for="product in relevantProducts" :key="product.key" :value="product.key">{{ localized(product) }}</option></select></label><label>{{ c('أساس الاعتبار', 'Prior basis') }}<select v-model="prior.basis"><option value="ADMIN_APPROVED_HYPOTHESIS">{{ c('فرضية تعتمدها الإدارة', 'Admin-approved hypothesis') }}</option><option value="EVIDENCE_SUPPORTED_PRIOR">{{ c('اعتبار تدعمه الأدلة', 'Evidence-supported prior') }}</option></select></label><label>{{ c('الأساس الموثّق', 'Documented basis') }}<textarea v-model="prior.documented_basis" required /></label><label>{{ c('مجال الانطباق', 'Applicability') }}<textarea v-model="prior.applicability" required /></label><label>{{ c('الحدود', 'Limits') }}<textarea v-model="prior.limits" required /></label><label>{{ c('المبرر الظاهر بالعربية', 'Public Arabic rationale') }}<textarea v-model="prior.rationale_ar" dir="rtl" required /></label><label>{{ c('المبرر الظاهر بالإنجليزية', 'Public English rationale') }}<textarea v-model="prior.rationale_en" dir="ltr" required /></label><label>{{ c('المبرر الداخلي', 'Internal rationale') }}<textarea v-model="prior.internal_rationale" dir="auto" required /></label><label class="catalog-check"><input v-model="prior.approved" type="checkbox" />{{ c('موافقة على هذا الاعتبار بعد مراجعته', 'Approve this prior after review') }}</label><label class="catalog-check"><input v-model="prior.active" type="checkbox" />{{ c('تفعيل', 'Activate') }}</label><p v-for="(message, field) in prior.errors" :key="field" class="catalog-error" role="alert">{{ message }}</p><p v-if="prior.recentlySuccessful" role="status">{{ c('تم الحفظ؛ حالة الموافقة أعلاه هي الحالة الحالية.', 'Saved; the approval status above reflects the current state.') }}</p><button :disabled="prior.processing">{{ prior.processing ? c('جارٍ الحفظ…', 'Saving…') : c('حفظ الاعتبار', 'Save prior') }}</button></form>
        </details>
    </article>
</template>

<style scoped>.catalog-provider{display:inline-flex;align-items:center;gap:10px}</style>
